    name: "prosthetics",
    means: "A jaw with two teeth missing, and a denture waiting above the gap: under the pointer it comes down into place.",
    rules: [1, 4, 5, 8],
    range: [16, 24, 30],
    tour: [[200, 140], [240, 190], null],
